import "./Footer.css";

function Footer() {
  return (
    <footer className="footer">
      <p>
        Projeto acadêmico sem fins comerciais. Pokémon e seus nomes/personagens
        pertencem aos seus respectivos titulares. Este projeto não é afiliado,
        patrocinado ou aprovado pela Nintendo, Game Freak, Creatures ou The
        Pokémon Company. Dados obtidos via PokéAPI.
      </p>
    </footer>
  );
}

export default Footer;
